authority.policy:
@id("alice-may-prompt-pr-commenter")
permit(
  principal == Dekopon::Principal::"alice",
  action == Dekopon::Action::"agent.prompt",
  resource == Dekopon::Agent::"pr-commenter"
)
when {
  context has via && context.via == "chat-gateway"
};

@id("alice-may-comment")
permit(
  principal == Dekopon::Principal::"alice",
  action == Dekopon::Action::"gh.pull-request.comment",
  resource == Dekopon::Provider::"gh"
)
when {
  context has agent && context.agent == "pr-commenter" &&
  context has via && context.via == "chat-gateway"
};
